clamp-helper.main.c:
#include <stdio.h>
int clamp(int x,int lo,int hi){if(x<lo)return lo;if(x>hi)return hi;return x;}
int main(void){int x,l,h;if(scanf("%d %d %d",&x,&l,&h)!=3)return 1;printf("clamped=%d\n",clamp(x,l,h));return 0;}

clamp-helper-gold.main.c:
