int clamp(int x,int lo,int hi){if(x<lo)return lo;if(x>hi)return hi;return x;}
int main(void){int l,h,x,y,z;if(scanf("%d %d %d %d %d",&l,&h,&x,&y,&z)!=5)return 1;int a=clamp(x,l,h),b=clamp(y,l,h),c=clamp(z,l,h);printf("values=%d %d %d sum=%d\n",a,b,c,a+b+c);return 0;}

compare-swap.main.c:
#include <stdio.h>
void compareSwap(int *a,int *b){if(*a>*b){int t=*a;*a=*b;*b=t;}}
int main(void){int a,b;if(scanf("%d %d",&a,&b)!=2)return 1;compareSwap(&a,&b);printf("%d %d\n",a,b);return 0;}

