vowel-scanner.main.c:
#include <stdio.h>
#include <ctype.h>
int main(void){char w[64];int n=0;if(scanf("%63s",w)!=1)return 1;for(int i=0;w[i];i++){int c=tolower((unsigned char)w[i]);if(c=='a'||c=='e'||c=='i'||c=='o'||c=='u')n++;}printf("vowels=%d\n",n);return 0;}

