point-manhattan.main.c:
#include <stdio.h>
#include <stdlib.h>
typedef struct{int x,y;} Point;
int main(void){Point a,b;if(scanf("%d %d %d %d",&a.x,&a.y,&b.x,&b.y)!=4)return 1;printf("distance=%d\n",abs(a.x-b.x)+abs(a.y-b.y));return 0;}

